def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = []
    for ch in string:
        code = ord(ch)
        if 97 <= code <= 122:
            result.append(chr(code - 32))
        elif 65 <= code <= 90:
            result.append(chr(code + 32))
        else:
            result.append(ch)
    return "".join(result)

