def decimal_to_binary(decimal):
    n = int(decimal) & 0xFFFFFFFF
    if n == 0:
        return "db0db"
    digits = []
    while n:
        digits.append('01'[n & 1])
        n >>= 1
    return "db" + "".join(reversed(digits)) + "db"

