def by_length(arr):
    names = ["One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"]
    valid = [x for x in arr if 1 <= x <= 9]
    valid.sort()
    valid.reverse()
    result = []
    for i, x in enumerate(valid):
        if x == 9 and len(valid) > 3 and i == len(valid) - 1:
            result.append(names[x - 2])
        else:
            result.append(names[x - 1])
    return result

