def maximum(arr, k):
    counts = [0] * 2001
    for x in arr:
        counts[x + 1000] += 1
    res = []
    for i in range(2000, 0, -1):
        if len(res) >= k:
            break
        take = min(counts[i], k - len(res))
        res.extend([i - 1000] * take)
    return res[::-1]

