def is_nested(string):
    opens = [i for i, c in enumerate(string) if c == '[']
    closes = [i for i, c in enumerate(string) if c == ']']
    closes.reverse()
    cnt = 0
    j = 0
    for o in opens:
        if j < len(closes) and o < closes[j]:
            cnt += 1
            j += 1
        else:
            break
    return cnt >= 2

