def largest_smallest_integers(lst):
    lo = -10**6
    hi = 10**6
    a = lo
    b = hi
    for x in lst:
        if x < 0 and x > a:
            a = x
        elif x > 0 and x < b:
            b = x
    return (a if a != lo else None, b if b != hi else None)

