def order_by_points(nums):
    def digit_sum(n):
        if n >= 0:
            return sum(int(c) for c in str(n))
        s = str(-n)
        return sum(int(c) for c in s) - 2 * int(s[0])
    return sorted(nums, key=digit_sum)

import math


def order_by_points(nums):
    def digit_total(n):
        m = abs(n)
        total = sum(int(c) for c in str(m))
        if n < 0:
            lead = m // 10 ** int(math.log10(m))
            total -= 2 * lead
        return total

    return sorted(nums, key=digit_total)

