def get_max_triples(n):
    c0 = n // 3 + (1 if n % 3 >= 2 else 0)
    c1 = n - c0
    def c3(m):
        return m * (m - 1) * (m - 2) // 6 if m >= 3 else 0
    return c3(c0) + c3(c1)

