def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n < 2:
        return y
    if n < 4:
        return x
    if n % 2 == 0 or n % 3 == 0:
        return y
    if n % 5 == 0:
        return x if n == 5 else y
    i = 5
    while i * i < n:
        if n % i == 0 or n % (i + 2) == 0:
            return y
        i += 6
    return x

