def do_algebra(operator, operand):
    ops = list(operator)
    nums = list(operand)

    i = 0
    while i < len(ops):
        if ops[i] == '**':
            nums[i] = nums[i] ** nums[i + 1]
            del nums[i + 1]
            del ops[i]
        else:
            i += 1

    i = 0
    while i < len(ops):
        if ops[i] == '*':
            nums[i] = nums[i] * nums[i + 1]
            del nums[i + 1]
            del ops[i]
        elif ops[i] == '//':
            nums[i] = nums[i] // nums[i + 1]
            del nums[i + 1]
            del ops[i]
        else:
            i += 1

    result = nums[0]
    for op, n in zip(ops, nums[1:]):
        if op == '+':
            result += n
        else:
            result -= n
    return result

